    33  static UA_UInt32
    34  getUserWriteMask(UA_Server *server, const UA_Session *session,
    35                   const UA_Node *node) {
    36      if(session == &server->adminSession)
    37          return 0xFFFFFFFF; /* the local admin user has all rights */
    38      return node->writeMask &
    39          server->config.accessControl.getUserRightsMask(server, &server->config.accessControl,
    40                                                         &session->sessionId, session->sessionHandle,
    41                                                         &node->nodeId, node->context);
    42  }
    43
    44  static UA_Byte
    45  getAccessLevel(UA_Server *server, const UA_Session *session,
    46                 const UA_VariableNode *node) {
    47      if(session == &server->adminSession)
    48          return 0xFF; /* the local admin user has all rights */
    49      return node->accessLevel;
    50  }
    51
    52  static UA_Byte
    53  getUserAccessLevel(UA_Server *server, const UA_Session *session,
    54                     const UA_VariableNode *node) {
    55      if(session == &server->adminSession)
    56          return 0xFF; /* the local admin user has all rights */
    57      return node->accessLevel &
    58          server->config.accessControl.getUserAccessLevel(server, &server->config.accessControl,
    59                                                          &session->sessionId, session->sessionHandle,
    60                                                          &node->nodeId, node->context);
    61  }
    62
    63  static UA_Boolean
    64  getUserExecutable(UA_Server *server, const UA_Session *session,
    65                    const UA_MethodNode *node) {
    66      if(session == &server->adminSession)
    67          return true; /* the local admin user has all rights */
    68      return node->executable &
    69          server->config.accessControl.getUserExecutable(server, &server->config.accessControl,
    70                                                         &session->sessionId, session->sessionHandle,
    71                                                         &node->nodeId, node->context);
    72  }
