    77
    78  static UA_StatusCode
    79  readArrayDimensionsAttribute(const UA_VariableNode *vn, UA_DataValue *v) {
    80      UA_Variant_setArray(&v->value, vn->arrayDimensions,
    81                          vn->arrayDimensionsSize, &UA_TYPES[UA_TYPES_UINT32]);
    82      v->value.storageType = UA_VARIANT_DATA_NODELETE;
    83      return UA_STATUSCODE_GOOD;
    84  }
    85
    86  static void
    87  setScalarNoDelete(UA_Variant *v, const void * UA_RESTRICT p,
    88                    const UA_DataType *type) {
    89      UA_Variant_setScalar(v, (void*)(uintptr_t)p, type);
    90      v->storageType = UA_VARIANT_DATA_NODELETE;
    91  }
    92
    93  static UA_StatusCode
    94  readIsAbstractAttribute(const UA_Node *node, UA_Variant *v) {
    95      const UA_Boolean *isAbstract;
    96      switch(node->nodeClass) {
    97      case UA_NODECLASS_REFERENCETYPE:
    98          isAbstract = &((const UA_ReferenceTypeNode*)node)->isAbstract;
    99          break;
   100      case UA_NODECLASS_OBJECTTYPE:
   101          isAbstract = &((const UA_ObjectTypeNode*)node)->isAbstract;
   102          break;
   103      case UA_NODECLASS_VARIABLETYPE:
   104          isAbstract = &((const UA_VariableTypeNode*)node)->isAbstract;
   105          break;
   106      case UA_NODECLASS_DATATYPE:
   107          isAbstract = &((const UA_DataTypeNode*)node)->isAbstract;
   108          break;
   109      default:
   110          return UA_STATUSCODE_BADATTRIBUTEIDINVALID;
   111      }
   112
   113      setScalarNoDelete(v, isAbstract, &UA_TYPES[UA_TYPES_BOOLEAN]);
   114      v->storageType = UA_VARIANT_DATA_NODELETE;
   115      return UA_STATUSCODE_GOOD;
   116  }
